def v(noun):
    pf = noun.noun.pluriforme
    vc = "(adj.)"
    # Nominal M-pluriforms do not project onto verbalized adjective stems.
    if pf and pf != "m":
        vc = f"({pf})" + vc
    return Verb(
        noun.noun.verbete(anotated=True),
        verb_class=vc,
        definition=noun.noun.raw_definition,
    )

